// @ts-expect-error virtual module generated by rollup-plugin-ses-script
import { SES_SCRIPT } from "virtual:ses-script";

/**
 * Source of the sandbox Web Worker, authored as a self-contained string so it
 * can be turned into a Blob URL and run without a separate chunk or same-origin
 * file (mirrors how `ProteusBridge` inlines its shim script).
 *
 * The worker runs with the host page's origin, so the document's scripts must
 * never reach its globals: `fetch`, `import()`, storage. SES `lockdown()`
 * freezes the shared built-ins, and each module runs in its own `Compartment`,
 * whose global holds only the endowments in `loadModule`. SES rejects any
 * source containing `import(` (dynamic import is syntax, so no global can be
 * removed to block it) and every route to building code from a string. It
 * needs strict mode, hence the directive before the SES bundle.
 *
 * The worker talks to the host only through the `MessagePort` it receives
 * first, using structured-clone messages. A handler's sole capability is
 * `ctx.emit`, which posts an existing Proteus event back to the host to be
 * re-dispatched. See `protocol.ts` for the message shapes and `ScriptContext`.
 *
 * INVARIANT: never endow a compartment with anything that reaches the worker
 * global or performs I/O (timers included: `setTimeout` with a string argument
 * evaluates it outside the compartment), and never pass host capabilities in
 * via `postMessage`.
 */
export const WORKER_SCRIPT =
  '"use strict";\n' +
  (SES_SCRIPT as string) +
  /* js */ `
// Locale taming would turn toLocaleString into toString.
lockdown({ localeTaming: "unsafe", reporting: "none" });

let port;
const handlers = new Map();
const watchers = [];
const pendingEmits = new Map();
let nextEmitId = 1;

// Minimal JSON-pointer getter (same semantics as the host's getProteusValue).
function getByPointer(data, path) {
  if (!path || path === "/") return data;
  const parts = path.replace(/^\\//, "").split("/");
  let current = data;
  for (const raw of parts) {
    if (current == null) return undefined;
    const key = raw.replace(/~1/g, "/").replace(/~0/g, "~");
    current = current[key];
  }
  return current;
}

function register(name, fn) {
  if (typeof name !== "string" || typeof fn !== "function") {
    throw new Error("register(name, fn) requires a string name and a function");
  }
  handlers.set(name, fn);
}

function watch(path, fn) {
  if (typeof path !== "string" || typeof fn !== "function") {
    throw new Error("watch(path, fn) requires a string path and a function");
  }
  watchers.push({ fn, path });
}

// Evaluate one module's source in its own compartment, which exposes
// \`register\` and \`watch\` plus the harmless powers SES withholds by
// default. Handlers are keyed by "moduleName:handlerName" via a per-module
// register wrapper; watchers are collected globally (order = watch id).
function loadModule(moduleName, source) {
  const compartment = new Compartment({
    __options__: true,
    globals: {
      console,
      Date,
      Intl,
      Math,
      register: (name, fn) => register(moduleName + ":" + name, fn),
      watch,
    },
  });
  compartment.evaluate(source);
}

function emit(event) {
  const emitId = nextEmitId++;
  return new Promise((resolve) => {
    pendingEmits.set(emitId, resolve);
    port.postMessage({ emitId, event, type: "emit" });
  });
}

// The first message carries the port to the host; every later message
// arrives on that port.
self.onmessage = (e) => {
  self.onmessage = null;
  port = e.ports[0];
  port.onmessage = onPortMessage;
};

async function onPortMessage(e) {
  const msg = e.data;

  if (msg.type === "init") {
    for (const [moduleName, source] of Object.entries(msg.scripts ?? {})) {
      try {
        loadModule(moduleName, source);
      } catch (err) {
        // A broken module leaves its handlers unregistered; invokes for them
        // surface a "not found" error at call time.
      }
    }
    // Report watched paths so the host can edge-detect and drive runWatcher.
    port.postMessage({ paths: watchers.map((w) => w.path), type: "watchers" });
    return;
  }

  if (msg.type === "emitResult") {
    const resolve = pendingEmits.get(msg.emitId);
    if (resolve) {
      pendingEmits.delete(msg.emitId);
      resolve(msg.result);
    }
    return;
  }

  if (msg.type === "invoke") {
    const { data, handler, invokeId, params } = msg;
    const fn = handlers.get(handler);
    if (!fn) {
      port.postMessage({
        error: 'No script handler registered for "' + handler + '"',
        invokeId,
        result: undefined,
        type: "invokeResult",
      });
      return;
    }
    const ctx = {
      emit,
      getValue: (path) => getByPointer(data, path),
    };
    try {
      const result = await fn(ctx, params ?? {});
      port.postMessage({ invokeId, result, type: "invokeResult" });
    } catch (err) {
      port.postMessage({
        error: err && err.message ? String(err.message) : String(err),
        invokeId,
        result: undefined,
        type: "invokeResult",
      });
    }
    return;
  }

  if (msg.type === "runWatcher") {
    const { current, data, previous, watchId } = msg;
    const watcher = watchers[watchId];
    if (!watcher) {
      return;
    }
    const ctx = {
      emit,
      getValue: (path) => getByPointer(data, path),
    };
    try {
      // Fire-and-forget: watchers return nothing to any caller. Errors are
      // swallowed to match the fail-silent default of the other ops.
      await watcher.fn(ctx, current, previous);
    } catch (err) {
      // Intentionally ignored.
    }
  }
}
`;
